// Helper to adjust hex color brightness for 3D extrusion lighting effects
const adjustColorBrightness = (hex: string, percent: number): string => {
  const num = parseInt(hex.replace("#", ""), 16);
  const amt = Math.round(2.55 * percent);
  const R = (num >> 16) + amt;
  const G = ((num >> 8) & 0x00ff) + amt;
  const B = (num & 0x0000ff) + amt;
  return (
    "#" +
    (
      0x1000000 +
      (R < 255 ? (R < 0 ? 0 : R) : 255) * 0x10000 +
      (G < 255 ? (G < 0 ? 0 : G) : 255) * 0x100 +
      (B < 255 ? (B < 0 ? 0 : B) : 255)
    )
      .toString(16)
      .slice(1)
  );
};

// Deterministic pseudo-random values for fat mass particles to remain pure and synchronized
const PARTICLE_COUNT = 100;
const particles = Array.from({ length: PARTICLE_COUNT }, (_, i) => {
  const randomVal = (seed: number) => {
    const x = Math.sin(seed) * 10000;
    return x - Math.floor(x);
  };
  return {
    id: i,
    x: 150 - randomVal(i * 12 + 1) * 105, // Distributed within left half of silhouette
    startY: randomVal(i * 34 + 2) * 380 + 70, // Height distribution
    size: randomVal(i * 56 + 3) * 5 + 1.5, // Particle radius
    speed: randomVal(i * 78 + 4) * 2.5 + 1.2, // Drift velocity
    opacity: randomVal(i * 90 + 5) * 0.6 + 0.4,
  };
});

