// 3D Isometric-Tilted Donut Chart Component using stacked layer extrusion
interface DonutChartProps {
  fatPercent: number;
  musclePercent: number;
  fatColor: string;
  muscleColor: string;
}

const DonutChart: React.FC<DonutChartProps> = ({
  fatPercent,
  musclePercent,
  fatColor,
  muscleColor,
}) => {
  const total = fatPercent + musclePercent;
  const fatProgress = total > 0 ? fatPercent / total : 0;
  const muscleProgress = total > 0 ? musclePercent / total : 0;

  // Use makePie to generate contiguous SVG slices
  const { path: fatPath } = makePie({ radius: 80, progress: fatProgress, rotation: -Math.PI / 2 });
  const { path: musclePath } = makePie({ radius: 80, progress: muscleProgress, rotation: -Math.PI / 2 + fatProgress * Math.PI * 2 });

  const depth = 14; // Number of layered slices for 3D depth
  const layers = [];

  for (let i = depth; i >= 0; i--) {
    const isTop = i === 0;
    const colorFat = isTop ? fatColor : adjustColorBrightness(fatColor, -35);
    const colorMuscle = isTop ? muscleColor : adjustColorBrightness(muscleColor, -35);

    layers.push(
      <g key={i} style={{ transform: `translateY(${i}px)`, transition: "none" }}>
        {fatProgress > 0 && <path d={fatPath} fill={colorFat} />}
        {muscleProgress > 0 && <path d={musclePath} fill={colorMuscle} />}
      </g>
    );
  }

  const maskId = React.useId().replace(/:/g, "");

  return (
    <div
      style={{
        transform: "scaleY(0.55) rotate(-12deg)",
        width: 170,
        height: 170,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "visible",
        filter: "drop-shadow(0 15px 25px rgba(0,0,0,0.65))",
        transition: "none",
      }}
    >
      <svg width="200" height="200" viewBox="0 0 160 160" style={{ overflow: "visible", transition: "none" }}>
        <defs>
          <mask id={maskId}>
            <rect x="-100" y="-100" width="400" height="400" fill="white" />
            <circle cx="80" cy="80" r="32" fill="black" />
          </mask>
        </defs>
        <g mask={`url(#${maskId})`}>
          {layers}
        </g>
      </svg>
    </div>
  );
};

