export const DexaScanAnimation: React.FC<DexaScanAnimationProps> = ({
  backgroundColor = "#060913",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "DEXA",
  subtitle = "BODY COMPOSITION SCAN",
  fatMassColor = "#ffcc00",
  muscleMassColor = "#e60000",
  initialFatPercent = 75,
  finalFatPercent = 97,
  initialMusclePercent = 25,
  finalMusclePercent = 3,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Primary animation timing triggers
  const introBodySpring = spring({ frame: frame - 10, fps, config: { damping: 14 } });
  const laserProgress = interpolate(frame, [25, 65], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  const initialBoxSpring = spring({ frame: frame - 40, fps, config: { damping: 15 } });
  const transformArrowSpring = spring({ frame: frame - 75, fps, config: { damping: 12 } });
  const finalBoxSpring = spring({ frame: frame - 95, fps, config: { damping: 15 } });

  // Right-side metrics animation calculations
  const fatVal1 = Math.round(interpolate(initialBoxSpring, [0, 1], [0, initialFatPercent], { extrapolateRight: "clamp" }));
  const muscleVal1 = Math.round(interpolate(initialBoxSpring, [0, 1], [0, initialMusclePercent], { extrapolateRight: "clamp" }));

  const fatVal2 = Math.round(interpolate(finalBoxSpring, [0, 1], [initialFatPercent, finalFatPercent], { extrapolateRight: "clamp" }));
  const muscleVal2 = Math.round(interpolate(finalBoxSpring, [0, 1], [initialMusclePercent, finalMusclePercent], { extrapolateRight: "clamp" }));

  // Fluid muscle scan line projection position
  const scanLineY = interpolate(Math.sin(frame * 0.07), [-1, 1], [65, 455]);

  // Drainage & dissolve particle timeline variables
  const drainTriggerFrame = 95;
  const drainProgress = Math.max(0, frame - drainTriggerFrame);
  const fatDissolveOpacity = interpolate(frame, [100, 170], [1.0, 0.15], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const driftSpeedFactor = interpolate(frame, [95, 140], [1, 2.8], { extrapolateRight: "clamp" });

  // Body Scan Outline coordinates
  const rightBodyPath = "M 150,50 " +
    "C 163,50 171,58 171,72 " +
    "C 171,82 166,88 159,92 " +
    "C 169,96 183,102 196,115 " +
    "C 203,122 213,135 219,155 " +
    "C 223,170 221,195 213,215 " +
    "C 209,225 201,230 193,225 " +
    "C 186,220 189,205 191,190 " +
    "C 193,175 189,160 183,150 " +
    "C 189,175 186,205 181,235 " +
    "C 176,265 179,310 183,350 " +
    "C 187,380 190,420 188,450 " +
    "C 186,465 179,470 166,470 " +
    "C 159,470 153,465 151,455 " +
    "L 151,475 L 150,475 Z";

  const resolvedBg = transparentBackground ? "transparent" : backgroundColor;
  const leftPanelWidth = width * 0.44;
  const rightPanelWidth = width * 0.56;

  // Responsive SVG Body Frame height & scale calculations
  const bodySvgHeight = height * 0.76;
  const bodySvgWidth = bodySvgHeight * 0.6;

  return (
    <AbsoluteFill style={{ backgroundColor: resolvedBg, fontFamily: spaceGroteskFamily, overflow: "hidden", transition: "none" }}>
      <BackgroundGrid />

      {/* Main Split Screen Arrangement */}
      <div style={{ display: "flex", flexDirection: "row", width: "100%", height: "100%", transition: "none" }}>
        
        {/* Left Panel: DEXA 3D Silhouette Scan */}
        <div style={{ width: leftPanelWidth, height: "100%", position: "relative", borderRight: "1px solid rgba(255, 255, 255, 0.05)", transition: "none" }}>
          
          {/* Header Identity Block */}
          <div style={{ position: "absolute", top: height * 0.07, left: width * 0.045, display: "flex", flexDirection: "column", gap: "2px", transition: "none" }}>
            <span style={{ fontSize: "44px", fontWeight: "900", color: "#ffffff", letterSpacing: "3px", lineHeight: "1", transition: "none" }}>
              {title}
            </span>
            <span style={{ fontSize: "14px", fontWeight: "600", color: "#a0a5b8", letterSpacing: "2.5px", transition: "none" }}>
              {subtitle}
            </span>
          </div>

          {/* Color Key / Legend Block */}
          <div
            style={{
              position: "absolute",
              top: height * 0.07,
              right: "40px",
              display: "flex",
              flexDirection: "column",
              gap: "8px",
              backgroundColor: "rgba(255, 255, 255, 0.03)",
              border: "1px solid rgba(255, 255, 255, 0.06)",
              borderRadius: "8px",
              padding: "10px 14px",
              transition: "none",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "11px", fontWeight: "700", color: "#9ca3af", transition: "none" }}>
              <div style={{ width: "11px", height: "11px", backgroundColor: fatMassColor, borderRadius: "2px", transition: "none" }} />
              FAT MASS
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "11px", fontWeight: "700", color: "#9ca3af", transition: "none" }}>
              <div style={{ width: "11px", height: "11px", backgroundColor: muscleMassColor, borderRadius: "2px", transition: "none" }} />
              MUSCLE MASS
            </div>
          </div>

          {/* Interactive Silhouette Center Area */}
          <div
            style={{
              width: "100%",
              height: "100%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              paddingTop: height * 0.08,
              boxSizing: "border-box",
              transition: "none",
            }}
          >
            <div
              style={{
                width: bodySvgWidth,
                height: bodySvgHeight,
                opacity: introBodySpring,
                transform: `scale(${interpolate(introBodySpring, [0, 1], [0.93, 1])})`,
                transition: "none",
              }}
            >
              <svg width="100%" height="100%" viewBox="0 0 300 500" style={{ overflow: "visible", transition: "none" }}>
                <defs>
                  {/* Dynamic Silhouette Mask Definitions */}
                  <mask id="right-muscle-mask">
                    <rect x="0" y="0" width="300" height="500" fill="black" />
                    <path d={rightBodyPath} fill="white" />
                  </mask>
                  <mask id="left-fat-mask">
                    <rect x="0" y="0" width="300" height="500" fill="black" />
                    <path d={rightBodyPath} fill="white" transform="translate(300, 0) scale(-1, 1)" />
                  </mask>
                </defs>

                {/* 3D Circular Base Platforms */}
                <ellipse cx="150" cy="465" rx="100" ry="24" fill="none" stroke="rgba(255,255,255,0.12)" strokeWidth={1.5} />
                <ellipse cx="150" cy="465" rx="122" ry="30" fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth={1} />
                <ellipse cx="150" cy="465" rx="70" ry="18" fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth={1} />

                {/* Left Side: Draining Fat Mass Representation */}
                <g opacity={fatDissolveOpacity} style={{ transition: "none" }}>
                  {/* Glowing Wireframe Silhouette Path */}
                  <path
                    d={rightBodyPath}
                    fill="none"
                    stroke={fatMassColor}
                    strokeWidth={2}
                    strokeDasharray="4 4"
                    transform="translate(300, 0) scale(-1, 1)"
                    opacity={0.4}
                  />

                  {/* Flowing Fluid Particles clipped strictly inside left half of body */}
                  <g mask="url(#left-fat-mask)">
                    {particles.map((p) => {
                      // Custom continuous downward flow, accelerating during transformation
                      const particleDeltaY = drainProgress * p.speed * driftSpeedFactor;
                      const currentY = ((p.startY - 70 + particleDeltaY) % 380) + 70;
                      
                      // Slight sideways drift away during active drainage phase
                      const driftLeft = drainProgress > 0 ? Math.min(60, (currentY - p.startY) * 0.12) : 0;
                      const currentX = p.x - driftLeft;

                      return (
                        <g key={p.id}>
                          {/* Inner white high-intensity nucleus */}
                          <circle
                            cx={currentX}
                            cy={currentY}
                            r={p.size}
                            fill="#ffffff"
                            opacity={p.opacity}
                          />
                          {/* Outer bright neon glow aura */}
                          <circle
                            cx={currentX}
                            cy={currentY}
                            r={p.size * 2}
                            fill={fatMassColor}
                            opacity={p.opacity * 0.35}
                          />
                        </g>
                      );
                    })}
                  </g>
                </g>

                {/* Right Side: Solid Muscle Mass Representation */}
                <g>
                  {/* Glowing Solid Red Underlay Base */}
                  <path
                    d={rightBodyPath}
                    fill="rgba(230,0,0,0.15)"
                    stroke={muscleMassColor}
                    strokeWidth={2.5}
                    style={{ filter: `drop-shadow(0 0 10px rgba(230,0,0,0.4))` }}
                  />

                  {/* Muscle anatomy overlays clipped strictly inside right half of body */}
                  <g mask="url(#right-muscle-mask)">
                    {muscleStrands.map((pathStr, index) => {
                      // Staggered muscle highlight scan reveal
                      const revealLimit = index * 4 + 20;
                      const strandOpacity = interpolate(frame, [revealLimit, revealLimit + 20], [0, 0.45], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
                      return (
                        <path
                          key={index}
                          d={pathStr}
                          fill="none"
                          stroke={muscleMassColor}
                          strokeWidth={1.5}
                          opacity={strandOpacity}
                        />
                      );
                    })}
                  </g>
                </g>

                {/* Central Scan Axis Division Glow Line */}
                <line x1="150" y1="50" x2="150" y2="465" stroke="#ffffff" strokeWidth={1} opacity={0.3} />
                <line x1="150" y1="50" x2="150" y2="465" stroke={fatMassColor} strokeWidth={3} opacity={0.15} style={{ filter: "blur(4px)" }} />

                {/* Laser scan line overlay sweeps across left body portion */}
                <g mask="url(#left-fat-mask)">
                  <line
                    x1="20"
                    y1={scanLineY}
                    x2="150"
                    y2={scanLineY}
                    stroke="#ffffff"
                    strokeWidth={2}
                    opacity={0.8}
                  />
                  <line
                    x1="20"
                    y1={scanLineY}
                    x2="150"
                    y2={scanLineY}
                    stroke={fatMassColor}
                    strokeWidth={6}
                    opacity={0.5}
                    style={{ filter: "blur(3px)" }}
                  />
                </g>
              </svg>
            </div>
          </div>
        </div>

        {/* Right Panel: Metric Progression Dashboard */}
        <div
          style={{
            width: rightPanelWidth,
            height: "100%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            paddingRight: width * 0.045,
            boxSizing: "border-box",
            gap: "5px",
            transition: "none",
          }}
        >
          {/* Top Section: INITIAL SCAN */}
          <BoxSection
            title="INITIAL SCAN"
            fatPercent={fatVal1}
            musclePercent={muscleVal1}
            fatColor={fatMassColor}
            muscleColor={muscleMassColor}
            opacity={initialBoxSpring}
            scale={interpolate(initialBoxSpring, [0, 1], [0.96, 1])}
          />

          {/* Dynamic Staggered Down Arrow */}
          <div
            style={{
              opacity: transformArrowSpring,
              transform: `translateY(${interpolate(Math.sin(frame * 0.12), [-1, 1], [-4, 4])}px)`,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              margin: "8px 0",
              transition: "none",
            }}
          >
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
              <path d="M6 7L12 13L18 7" stroke="#6b7280" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
              <path d="M6 13L12 19L18 13" stroke={fatMassColor} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" opacity={0.8} />
            </svg>
          </div>

          {/* Bottom Section: AFTER TRANSFORMATION (Showing dramatic drop to 3%) */}
          <BoxSection
            title="AFTER TRANSFORMATION"
            fatPercent={fatVal2}
            musclePercent={muscleVal2}
            fatColor={fatMassColor}
            muscleColor={muscleMassColor}
            opacity={finalBoxSpring}
            scale={interpolate(finalBoxSpring, [0, 1], [0.96, 1])}
          />
        </div>

      </div>
    </AbsoluteFill>
  );
};

